package com.hbm.client.bomb.nuclear;
import com.mojang.blaze3d.vertex.VertexConsumer;import net.minecraft.client.Camera;import net.minecraft.client.Minecraft;import net.minecraft.client.multiplayer.ClientLevel;import net.minecraft.client.particle.*;import net.minecraft.client.renderer.texture.TextureAtlas;import net.minecraft.resources.ResourceLocation;import net.minecraft.util.Mth;import net.minecraft.world.phys.AABB;
/** ClientProxy vanillaExt/volcano: exact no-clip vanilla smoke growth, scale100,200..249life and original velocity. */
public final class LegacyVolcanoSmokeParticle extends Particle{private final float shade;public LegacyVolcanoSmokeParticle(ClientLevel level,double x,double y,double z){super(level,x,y,z);shade=random.nextFloat()*.3F;lifetime=200+random.nextInt(50);yd=2.5+random.nextDouble();xd=random.nextGaussian()*.2;zd=random.nextGaussian()*.2;hasPhysics=false;}@Override public void tick(){xo=x;yo=y;zo=z;if(age++>=lifetime){remove();return;}yd+=.004;move(xd,yd,zd);xd*=.96;yd*=.96;zd*=.96;}@Override public ParticleRenderType getRenderType(){return MukeRenderTypes.ORDERED;}@Override public AABB getRenderBoundingBox(float partial){return new AABB(x-15,y-15,z-15,x+15,y+15,z+15);}@Override public void render(VertexConsumer ignored,Camera camera,float partial){if(MukeRenderTypes.defer(this,partial))return;var out=MukeRenderTypes.begin(MukeRenderTypes.VANILLA_SMOKE);var eye=camera.getPosition();int frame=Math.max(0,7-age*8/lifetime);var sprite=((TextureAtlas)Minecraft.getInstance().getTextureManager().getTexture(TextureAtlas.LOCATION_PARTICLES)).getSprite(ResourceLocation.withDefaultNamespace("generic_"+frame));float scale=.1F*100*Mth.clamp((age+partial)/lifetime*32F,0,1);float px=(float)(Mth.lerp(partial,xo,x)-eye.x),py=(float)(Mth.lerp(partial,yo,y)-eye.y),pz=(float)(Mth.lerp(partial,zo,z)-eye.z);var corners=new org.joml.Vector3f[]{new org.joml.Vector3f(-1,-1,0),new org.joml.Vector3f(-1,1,0),new org.joml.Vector3f(1,1,0),new org.joml.Vector3f(1,-1,0)};float[] us={sprite.getU1(),sprite.getU1(),sprite.getU0(),sprite.getU0()},vs={sprite.getV1(),sprite.getV0(),sprite.getV0(),sprite.getV1()};for(int i=0;i<4;i++){var vertex=corners[i].rotate(camera.rotation()).mul(scale).add(px,py,pz);out.addVertex(vertex.x,vertex.y,vertex.z).setUv(us[i],vs[i]).setColor(shade,shade,shade,1).setLight(getLightColor(partial));}}}
